which iverilog vvp && iverilog -V 2>/dev/null | head -2; mkdir -p /tmp/pt && cd /tmp/pt && cat > d.v <<'EOF'
module sub #(parameter WIDTH = 4)();
  initial $display("SUB WIDTH %0d", WIDTH);
endmodule
module top;
  parameter DEPTH = 2;
  sub U_DUT();
  initial $display("TOP DEPTH %0d", DEPTH);
endmodule
EOF
cat > tb.v <<'EOF'
`timescale 1ns/1ps
module tb;
  top u();
  initial begin
    $display("ASSERT PASS ok");
    $display("COVER c");
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sim.vvp -s tb -Ptop.DEPTH=9 -Ptop.U_DUT.WIDTH=16 d.v tb.v && vvp -n sim.vvp +SEED=0

cd /tmp/pt && cat > tb2.v <<'EOF'
`timescale 1ns/1ps
module tb;
  initial begin
    $display("ASSERT PASS ok");
    $display("COVER c");
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sim2.vvp -s top -s tb -Ptop.DEPTH=9 -Ptop.U_DUT.WIDTH=16 d.v tb2.v && vvp -n sim2.vvp +SEED=0; echo "---bad param---"; iverilog -g2012 -o sim3.vvp -s top -Ptop.NOPE=9 d.v; echo "rc=$?"

man iverilog 2>/dev/null | grep -A8 'Ppath'; echo "==="; cd /tmp/pt && cat > d2.v <<'EOF'
module sub #(parameter WIDTH = 4)();
  initial $display("SUB WIDTH %0d", WIDTH);
endmodule
module top;
  sub U_DUT();
endmodule
EOF
iverilog -g2012 -o s6.vvp -s top -Ptop.U_DUT.WIDTH=16 d2.v && vvp -n s6.vvp

cd /tmp/pt && cat > ov.v <<'EOF'
module __rtl_lab_params;
  defparam top.U_DUT.WIDTH = 16;
