endmodule
EOF
iverilog -g2012 -o s7.vvp -s top -s __rtl_lab_params d2.v ov.v 2>&1; echo "rc=$?"; vvp -n s7.vvp; echo "--- bad path ---"; cat > ov2.v <<'EOF'
