  defparam top.NOPE.WIDTH = 16;
endmodule
EOF
iverilog -g2012 -o s8.vvp -s top -s __rtl_lab_params d2.v ov2.v 2>&1; echo "rc=$?"

cd /tmp/pt && iverilog -g2012 -o s9.vvp -s top -s __rtl_lab_params d.v ov.v 2>&1; echo "rc=$?"; vvp -n s9.vvp; echo "--- bad param name at root via defparam ---"; cat > ov3.v <<'EOF'
