iverilog -g2012 -o s10.vvp -s top -s __rtl_lab_params d.v ov3.v 2>&1; echo "rc=$?"

cd /tmp/pt && cat > tbp.v <<'EOF'
`timescale 1ns/1ps
module tb;
  parameter WIDTH = 4;
  initial begin
    $display("WIDTH %0d", WIDTH);
    #5 $finish;
  end
endmodule
EOF
iverilog -g2012 -o sp.vvp -s tb -Ptb.WIDTH=8 tbp.v 2>&1; echo "rc=$?"; vvp -n sp.vvp; echo "--- empty value ---"; iverilog -g2012 -o sp2.vvp -s tb -Ptb.WIDTH= tbp.v 2>&1; echo "rc=$?"

